class Student {
  +studentID : int
  +birthDate : date
  +birthCity : string
  +birthRegion : string
  +enrollmentYear : int
}
class Professor {
  +name : string
  +birthDate : date
  +birthCity : string
}
class Faculty {
  +name : string
  +type : string
}
class Course {
  +code : string
  +lectureHours : int
}
class Exam {
  +grade : float
}

Student "1" -- "1" Faculty : is enrolled in
Student "1" -- "*" Exam : passes
Course "1" -- "*" Exam : is part of
Professor "1" -- "*" Course : teaches
Course "*" -- "1" Faculty : belongs to
@enduml

